package main

import (
	"crypto/ecdsa"
	"crypto/ed25519"
	"crypto/elliptic"
	"crypto/sha256"
	"encoding/base64"
	"encoding/binary"
	"fmt"
	"math/big"

	"golang.org/x/mod/sumdb/note"
)

// The example keys are derived from fixed, public seeds, like the test keys
// of any test suite: they protect nothing and are published on purpose, so
// the examples can be regenerated byte for byte. Their names use the
// reserved .example domain so they can never be mistaken for real ones.

func seed(label string) []byte {
	s := sha256.Sum256([]byte("diagnos-tech/audit examples, not a secret: " + label))
	return s[:]
}

// logSigner returns a signed-note Ed25519 signer and its vkey.
func logSigner(name string) (note.Signer, string, error) {
	priv := ed25519.NewKeyFromSeed(seed("log key: " + name))
	pub := priv.Public().(ed25519.PublicKey)
	vkey, err := note.NewEd25519VerifierKey(name, pub)
	if err != nil {
		return nil, "", err
	}
	alg := append([]byte{0x01}, pub...)
	h := sha256.Sum256(append([]byte(name+"\n"), alg...))
	skey := fmt.Sprintf("PRIVATE+KEY+%s+%08x+%s", name, binary.BigEndian.Uint32(h[:]),
		base64.StdEncoding.EncodeToString(append([]byte{0x01}, priv.Seed()...)))
	signer, err := note.NewSigner(skey)
	return signer, vkey, err
}

func witnessKey(name string) ed25519.PrivateKey {
	return ed25519.NewKeyFromSeed(seed("witness key: " + name))
}

// p256Key derives an ECDSA P-256 key from a label.
func p256Key(label string) *ecdsa.PrivateKey {
	curve := elliptic.P256()
	d := new(big.Int).SetBytes(seed("p256: " + label))
	d.Mod(d, new(big.Int).Sub(curve.Params().N, big.NewInt(1)))
	d.Add(d, big.NewInt(1)) // 1 <= d < N
	x, y := curve.ScalarBaseMult(d.FillBytes(make([]byte, 32)))
	return &ecdsa.PrivateKey{PublicKey: ecdsa.PublicKey{Curve: curve, X: x, Y: y}, D: d}
}
